    while token:
        pidx, prev_ = ptoken.token_prev(tidx)

        # Skip whitespace to find the actual previous token
        while prev_ and prev_.is_whitespace and pidx > 0:
            pidx, prev_ = ptoken.token_prev(pidx)

        if prev_ and (
            isinstance(prev_, sql.Identifier) or 
            isinstance(prev_, sql.Function) or
            isinstance(prev_, sql.Operation) or
            prev_.ttype in T_NAME or 
            prev_.ttype in T_NUMERICAL
        ):
            # Get the index of the whitespace token if it exists
            widx, ws = ptoken.token_next(pidx)
            if ws and ws.is_whitespace and widx < tidx:
                # Group the identifier, whitespace, and order keyword
                ptoken.group_tokens(sql.Identifier, pidx, tidx)
            else:
                # No whitespace, just group the identifier and order keyword
                ptoken.group_tokens(sql.Identifier, pidx, tidx)
            tidx = pidx

        tidx, token = ptoken.token_next_by(t=T.Keyword.Order, idx=tidx)

